# (feastDate, English name, Turkish name, Turkish description, Turkish patronOf) - Protestant / Anglican calendars, January to June
DATA = [
    ("January 5", "George Washington Carver", "George Washington Carver", "Köle olarak doğan Amerikalı bilim insanı ve öğretmen (yaklaşık 1864-1943); yoksul çiftçilere toprağı ekin dönüşümü ve yer fıstığıyla yenilemeyi öğretti. Keşiflerinin onurunu, laboratuvardaki rehberi dediği Tanrı'ya verdi.", "Bilim insanları, çiftçiler, öğretmenler"),
    ("January 6", "The Epiphany of Our Lord", "Rabbimizin Epifanisi (Görünüşü)", "Bilge adamların ziyareti Mesih'in uluslara açıldığını gösterir. Lutheran ve Anglikan kiliseler Epifani'yi başlıca bayram olarak tutar; çoğu İsa'nın vaftizini ve Kana'daki düğünü de anar.", "Arayanlar, tüm uluslar"),
    ("January 8", "Jim Elliot and the Ecuador Missionaries", "Jim Elliot ve Ekvador Misyonerleri", "8 Ocak 1956'da beş genç Amerikalı misyoner, Jim Elliot, Nate Saint, Ed McCully, Pete Fleming ve Roger Youderian, Ekvador'un Waorani halkı tarafından öldürüldü. Aileleri sonradan geri dönüp müjdeyi paylaştı.", "Misyonerler, zulüm görenler"),
    ("January 9", "Julia Chester Emery", "Julia Chester Emery", "Kırk yıl boyunca Misyon Kurulu'nun Kadın Yardımcı Örgütü'nü yöneten ve kilisenin kadınlarını yurt içinde ve dışında misyona seferber etmeye yardım eden Amerikalı Episkopal önder (1852-1922).", "Misyon destekçileri, kilise çalışanları"),
    ("January 10", "William Laud", "William Laud", "İbadette düzen ve güzellik için çalışan ve İngiliz İç Savaşı'nda Parlamento tarafından idam edilen Canterbury Başpiskoposu (1573-1645). Birçok Anglikan tarafından saygıyla anılır.", "Kilise düzeni, kanaatleri için acı çekenler"),
    ("January 12", "Aelred of Rievaulx", "Rievaulx'lu Aelred", "Mesih'te dostluğun Tanrı'yı tanımanın bir yolu olduğunu öğreten 'Ruhsal Dostluk'u yazan İngiliz Sistersiyen başrahip (1110-1167). 600 keşişi nezaketle yönetti.", "Dostlar, başrahipler, cemaat arayanlar"),
    ("January 13", "Hilary of Poitiers", "Poitiers'li Hilary", "Mesih'in tam tanrılığını sürgün pahasına savunan ve ilahiler ile tefsirler yazan Poitiers Piskoposu (yaklaşık 310-367). Lutheran ve Anglikanlar onu imanın öğretmeni olarak onurlandırır.", "İlahiyatçılar, inanç bildirisinin savunucuları"),
    ("January 14", "Eivind Berggrav", "Eivind Berggrav", "Kilisenin Nazi işgaline direnişine önderlik eden, hapsedilen ve Kilise'nin adalet için ayakta durma görevi üzerine yazan Norveçli Lutheran piskopos (1884-1959).", "Piskoposlar, zulme direnenler"),
    ("January 15", "Martin Luther King Jr.", "Martin Luther King Jr.", "İncil'e dayalı şiddetsiz eylemle sivil haklar hareketine önderlik eden Amerikalı Baptist papaz (1929-1968). 1968'de Memphis'te suikasta kurban gitti. Lutheran ve Episkopal takvimleri onu anar.", "Sivil haklar, barış yapıcılar, papazlar"),
    ("January 18", "Amy Carmichael", "Amy Carmichael", "Hindistan'da elli beş yıl hizmet eden, çocukları tapınak hizmetinden kurtaran ve Dohnavur Topluluğu'nu kuran İrlandalı misyoner (1867-1951). Şair ve dua kadınıydı.", "Misyonerler, kurtarılan çocuklar"),
    ("January 19", "Henry of Uppsala", "Uppsala'lı Henry", "İsveç Kralı Eric ile Finlandiya misyonuna giden ve 'Finlandiya'nın havarisi' olarak onurlandırılan İngiltere doğumlu Uppsala piskoposu (ö. 1156). Disiplin verdiği bir adam tarafından öldürüldü.", "Finlandiya, İsveç, misyonerler"),
    ("January 22", "Vincent of Saragossa", "Saragossa'lı Vincent", "Mesih'i inkâr etmektense Diocletianus altında işkenceye dayanan İspanyol diyakoz ve şehit (ö. 304). Lutheranlar ve Anglikanlar onu erken şehitler arasında anar.", "Diyakozlar, zulüm görenler"),
    ("January 23", "Phillips Brooks", "Phillips Brooks", "Massachusetts Episkopal piskoposu (1835-1893); çağının büyük vaizlerinden biri ve 'O Little Town of Bethlehem' Noel ilahisinin yazarı.", "Vaizler, ilahi yazarları"),
    ("January 24", "Timothy, Pastor and Companion of Paul", "Timoteos, Papaz ve Pavlus'un Arkadaşı", "Annesi Eunike ve büyükannesi Lois tarafından çocukluktan Kutsal Yazılar öğretilen genç Efes papazı. Pavlus ona 'Rab'deki sevgili ve sadık oğlum' dedi.", "Genç papazlar, aileden öğrenenler"),
    ("January 27", "Lydia, Dorcas and Phoebe", "Lydia, Dorkas ve Phoebe", "Erken Kilise'de hizmet eden üç kadın: Filipi'de Pavlus'a evini açan mor kumaş satıcısı Lydia; Yafa'nın yoksulları için giysi diken Dorkas; ve Pavlus'un Romalılar'a mektubunu taşıyan Kenhreya diyakozu Phoebe.", "Ev sahipleri, pratik hizmet edenler"),
    ("January 28", "Thomas Aquinas", "Thomas Aquinas", "Summa Theologiae adlı eseri Hıristiyan düşüncesinin anıtı olmayı sürdüren Dominikan keşiş ve öğretmen (1225-1274). Lutheran ve Anglikan takvimleri onu Kilise'nin öğretmeni olarak onurlandırır.", "Öğrenciler, öğretmenler, ilahiyatçılar"),
    ("January 29", "Liliuokalani of Hawaii", "Hawaii'li Liliuokalani", "Hawaii Krallığı'nın son hüküm süren hükümdarı (1838-1917); dindar bir Hıristiyan, 'Aloha 'Oe' şarkısını yazan yetenekli bir besteci ve siyasi kayıp karşısında onurlu bir kadındı.", "Hawaii, müzisyenler, gücünü kaybedenler"),
    ("January 30", "Charles I, King and Martyr", "Kral ve Şehit I. Charles", "İç Savaş'tan sonra 30 Ocak 1649'da idam edilen İngiltere kralı. Duaların Ortak Kitabı bir dönem bu gün için bir ayin içeriyordu; birçok Anglikan bunu hâlâ anar.", "Vicdanı için acı çekenler"),
    ("January 31", "Charles Haddon Spurgeon", "Charles Haddon Spurgeon", "Onlarca yıl Londra'daki Metropolitan Tabernacle'da papazlık yapan, 'Vaizlerin Prensi' olarak bilinen İngiliz Baptist vaiz (1834-1892). Yetimhaneler ve bir papaz kolejini kurdu ve bu gün öldü.", "Vaizler, papazlar, yetimler"),

    ("February 3", "Anskar of Hamburg", "Hamburg'lu Anskar", "İncil'i Danimarka ve İsveç'e getiren 'Kuzey'in havarisi' Hamburg ve Bremen başpiskoposu (801-865). Lutheran ve Anglikan takvimlerinde anılır.", "İskandinavya, misyonerler"),
    ("February 4", "Dietrich Bonhoeffer's Birthday", "Dietrich Bonhoeffer'in Doğum Günü", "Nazi rejimine direnen ve 'Pahalı Müritlik'i yazan Alman Lutheran papaz ve ilahiyatçı (4 Şubat 1906'da doğdu). 1945'te idam edildi; hayatı 9 Nisan'da anılır.", "İlahiyatçılar, adaletsizliğe direnenler"),
    ("February 5", "Agatha of Sicily and the Martyrs of Japan", "Sicilya'lı Agatha ve Japonya Şehitleri", "Lutheranlar ve Anglikanlar, yaklaşık 251'de Sicilya'da şehit edilen Agatha'yı ve 1597'de Nagasaki'de çarmıha gerilen yirmi altı Hıristiyan'ı anar.", "Zulüm görenler, Japonya"),
    ("February 7", "Charles Dickens and the Christmas Carol", "Charles Dickens ve Noel Şarkısı", "Kitapları yoksulluğu ortaya koyan ve hayırseverliği teşvik eden İngiliz romancı (7 Şubat 1812'de doğdu). 'Bir Noel Şarkısı' insanların Noel'de cömertliği nasıl düşündüğünü şekillendirdi.", "Yazarlar, yoksullar için çalışanlar"),
    ("February 8", "Bakhita of Sudan, Remembered", "Sudan'lı Bakhita'nın Anılışı", "Episkopal Kilisesi, Darfur'da doğan, çocukken köle edilen ve sonradan İtalya'da rahibe ve öğretmen olan, kendisini köle edenleri affeden Josephine Bakhita'yı anar.", "İnsan ticareti mağdurları"),
    ("February 10", "Silas, Companion of Paul", "Silas, Pavlus'un Arkadaşı", "Pavlus'a ikinci yolculuğunda eşlik eden erken Kilise'nin peygamberi ve önderi. Filipi hapishanesinde Pavlus'la ilahiler söyledi.", "Misyoner arkadaşlar"),
    ("February 11", "Barbara Harris", "Barbara Harris", "1989'da Barbara Clementine Harris Anglikan Cemaati'nin ilk kadın piskoposu olarak kutsandı. Episkopal Kilisesi onun rahip, piskopos ve adalet savunucusu olarak hizmetini anar.", "Hizmetteki kadınlar, piskoposlar"),
    ("February 12", "Fanny Crosby", "Fanny Crosby", "Doğuştan kör olan ve 'Blessed Assurance' ile 'To God Be the Glory' dahil 8.000'den fazla ilahi yazan Amerikalı ilahi yazarı (1820-1915). Bu gün öldü.", "İlahi yazarları, körler"),
    ("February 13", "Aquila, Priscilla and Apollos", "Aquila, Priscilla ve Apollos", "Lutheran takvimi, belagatli Apollos'a 'Tanrı'nın yolunu daha doğru' öğreten çadırcı çifti ve sonra güçlü bir vaiz olan Apollos'u anar.", "Öğretmenler, evli çiftler, vaizler"),
    ("February 15", "Philemon and Onesimus", "Filimon ve Onesimus", "Kaçak kölesi Onesimus'un Pavlus'un, onu 'artık köle olarak değil sevgili kardeş olarak' kabul etmesini isteyen mektubuyla geri döndüğü Kolose'li Filimon.", "Uzlaşma, ezilenler"),
    ("February 16", "Philipp Melanchthon", "Philipp Melanchthon", "Luther'in meslektaşı ve Augsburg İtirafı'nın başlıca yazarı olan Alman bilgin (1497-1560). Eğitimdeki çalışması nedeniyle 'Almanya'nın Öğretmeni' denir.", "Öğretmenler, bilginler, itirafçılar"),
    ("February 17", "Janani Luwum", "Janani Luwum", "İdi Amin'in vahşetine karşı konuşan ve öldürülen Uganda Anglikan başpiskoposu (1922-1977). Modern bir şehit olarak onurlandırılır.", "Uganda, ezilenler için konuşanlar"),
    ("February 19", "Chinese Martyrs Agnes, Agatha and Lucy", "Çinli Şehitler Agnes, Agatha ve Lucy", "1856-1862 arasında şehit edilen, ilmihal öğretmeni olan üç Çinli Katolik kadın. Episkopal Kilisesi onların tanıklığını onurlandırır.", "Çin, ilmihal öğretmenleri"),
    ("February 20", "Frederick Douglass", "Frederick Douglass", "Köleliğe meydan okumak için Kutsal Yazılar'ı kullanan ve kadınların ve tüm insanların haklarını savunan kaçak köle ve kölelik karşıtı önder (yaklaşık 1818-1895). Bu gün öldü.", "Kölelik karşıtları, özgürlük arayanlar"),
    ("February 21", "Eric Liddell", "Eric Liddell", "Pazar günü koşmayı reddeden, sonra Çin'de misyoner olarak hizmet eden ve bir Japon esir kampında ölen İskoç Olimpiyat altın madalyalısı (1902-1945).", "Sporcular, misyonerler"),
    ("February 22", "Margaret of Cortona", "Cortona'lı Margaret", "Evlilik dışı bir ilişkiyi bırakan, Fransiskan üçüncü tarikat üyesi olan ve Cortona'nın yoksullarına ve hastalarına bakan İtalyan tövbekâr (1247-1297).", "Tövbe edenler, yoksullar"),
    ("February 24", "Matthias, Apostle", "Havari Matyas", "On İkiler arasında Yahuda'nın yerine kurayla seçildi. Lutheranlar onun gününü 24 Şubat'ta ya da artık yılda 25 Şubat'ta tutar; diğer gelenekler Mayıs'ta tutar.", "Sadakatle hizmet edenler, gözden kaçanlar"),
    ("February 25", "Elizabeth Fedde", "Elizabeth Fedde", "Amerika'da ilk Lutheran diyakoz evini kuran ve Brooklyn ve Minneapolis'te göçmenlere hizmet eden Norveçli Lutheran kadın diyakoz (1850-1921).", "Kadın diyakozlar, hemşireler, göçmenler"),
    ("February 26", "Photini, the Samaritan Woman at the Well", "Photini, Kuyudaki Samiriyeli Kadın", "İsa'nın Yakup'un kuyusunda karşılaştığı, su testisini bırakıp şehrine Mesih ile tanıştığını söylemek için koşan kadın. Episkopal Kilisesi onu müjdeci olarak onurlandırır.", "Müjdeciler, arayanlar"),
    ("February 28", "Anna Julia Cooper", "Anna Julia Cooper", "Köle olarak doğan, altmışlı yaşlarında doktora yapan ve eğitimin onura giden bir yol olduğunu öğreten Afro-Amerikalı eğitimci ve bilgin (1858-1964).", "Eğitimciler, bilginler"),

    ("March 2", "John and Charles Wesley", "John ve Charles Wesley", "Metodist hareketi başlatan Anglikan rahip kardeşler (John, 1703-1791; Charles, 1707-1788). Charles, 'Hark! The Herald Angels Sing' dahil altı binden fazla ilahi yazdı.", "Metodistler, ilahi yazarları, müjdeciler"),
    ("March 3", "John and Charles Wesley, Anglican Commemoration", "John ve Charles Wesley, Anglikan Anışı", "Episkopal Kilisesi, on sekizinci yüzyılda İngiltere Kilisesi'ni açık hava vaazları, küçük gruplar ve ilahilerle yenileyen kardeşleri anar.", "Kilise'nin yenileyicileri"),
    ("March 6", "Elizabeth Barrett Browning", "Elizabeth Barrett Browning", "İmanı ve sevgisi 'Portekizce'den Soneler' gibi eserleri şekillendiren İngiliz şair (1806-1861). Köleliğe ve çocuk işçiliğine karşı yazdı.", "Şairler, sosyal reformcular"),
    ("March 9", "Gregory of Nyssa, Bishop and Theologian", "Nyssalı Gregory, Piskopos ve İlahiyatçı", "Episkopal Kilisesi, İstanbul'da Teslis'i savunan ve ruhun Tanrı'da 'sürekli ilerleyişi' üzerine yazan Gregory'yi onurlandırır.", "İlahiyatçılar"),
    ("March 10", "Harriet Tubman and Sojourner Truth", "Harriet Tubman ve Sojourner Truth", "Harriet Tubman (yaklaşık 1822-1913) duayla yönlendirilerek Yeraltı Demiryolu ile yetmişten fazla kişiyi köleliğten çıkardı. Sojourner Truth (yaklaşık 1797-1883) özgürlüğü ve kadınların eşitliğini vaaz etti.", "Özgürlük arayanlar, cesur kadınlar"),
    ("March 12", "Gregory the Great", "Büyük Gregorius", "Augustinus'u İngiltere'ye gönderen, çobanlık bakımı üzerine yazan ve kendine 'Tanrı'nın kullarının kulu' diyen Roma piskoposu (yaklaşık 540-604). Lutheranlar ve Anglikanlar onu örnek bir papaz olarak onurlandırır.", "Papazlar, müzisyenler, öğretmenler"),
    ("March 13", "James Theodore Holly", "James Theodore Holly", "Haiti'ye taşınan ve orada on yıllarca Kilise'ye önderlik eden Episkopal Kilisesi'nin ilk Afro-Amerikalı piskoposu (1829-1911).", "Haiti, piskoposlar"),
    ("March 15", "Vincent de Paul and Louise de Marillac", "Vincent de Paul ve Louise de Marillac", "Yoksullara hizmet için Misyon Cemaati'ni ve Sevgi Kızları'nı kuran Fransız rahip (1581-1660) ve dul kadın (1591-1660).", "Sosyal hizmet uzmanları, yoksullara hizmet edenler"),
    ("March 20", "Cuthbert of Lindisfarne", "Lindisfarne'li Cuthbert", "Northumbria'nın yoksul köylerinde vaaz verip şifa dağıtarak yürüyen İngiliz keşiş, piskopos ve münzevi (yaklaşık 634-687).", "Çobanlar, kuzey İngiltere"),
    ("March 22", "Jonathan Edwards", "Jonathan Edwards", "Büyük Uyanış'ın önderlerinden olan, Stockbridge'de Mahican halkına misyoner olarak da hizmet eden ve Princeton başkanı olan Amerikalı papaz ve ilahiyatçı (1703-1758).", "İlahiyatçılar, misyonerler"),
    ("March 23", "Gregory the Illuminator", "Aydınlatıcı Gregory", "Kral Tiridates'i dönüştüren, ilk Hıristiyan devleti kuran ve Ermeni Kilisesi'nin babası olarak onurlandırılan Ermenistan'ın havarisi (yaklaşık 257-331).", "Ermenistan"),
    ("March 24", "Oscar Romero", "Oscar Romero", "Yoksullar için konuştuktan sonra 1980'de Ayin yaparken vurulan San Salvador Başpiskoposu. Lutheranlar, Anglikanlar ve Katolikler onu modern bir şehit olarak anar.", "El Salvador, yoksullar"),
    ("March 26", "Harriet Monsell", "Harriet Monsell", "İngiltere Kilisesi'nde kadınlar için erken bir dinî topluluk olan Aziz John Baptist Topluluğu'nun dul kurucusu İngiliz Anglikan (1811-1883).", "Rahibeler"),
    ("March 27", "Charles Henry Brent", "Charles Henry Brent", "Afyon ticaretinin sona ermesi ve Hıristiyan birliği için çalışan, İman ve Düzen hareketinin başlamasına yardım eden Filipinler'in Episkopal misyoner piskoposu (1862-1929).", "Misyonerler, ekümenistler"),
    ("March 28", "James Solomon Russell", "James Solomon Russell", "Virginia'da Afro-Amerikalı öğrenciler için Aziz Paul Normal ve Endüstri Okulu'nu kuran ve Güney'de kiliseye önderlik eden Episkopal rahip (1857-1935).", "Eğitimciler, Afro-Amerikalı kiliseler"),
    ("March 29", "Hans Nielsen Hauge", "Hans Nielsen Hauge", "Kişisel imana çağırarak ülkeyi dolaşan ve yoksullara yardım için işletmeler kuran Norveçli meslekten olmayan vaiz ve reformcu (1771-1824). Vaaz verdiği için hapsedildi.", "Meslekten olmayan vaizler, girişimciler"),
    ("March 30", "Mary of Egypt", "Mısırlı Meryem", "Günahlı bir hayatın ardından çölde kırk yedi yıl münzevi yaşayan beşinci yüzyıl Mısırlı tövbekârı. Hikâyesi birçok Kilise'de Oruç sırasında okunur.", "Tövbe edenler"),
    ("March 31", "John Donne", "John Donne", "St Paul Başpapazı olan, 'Hiçbir insan bir ada değildir' sözünü ve 'Death, be not proud' dahil 'Kutsal Soneler'i yazan Anglikan rahip ve şair (1572-1631).", "Şairler, vaizler"),

    ("April 1", "Frederick Denison Maurice", "Frederick Denison Maurice", "Hıristiyan sosyalizminin kurucularından olan ve İşçi Koleji'nin kurulmasına yardım eden İngiliz Anglikan rahip ve ilahiyatçı (1805-1872).", "Sosyal reformcular, eğitimciler"),
    ("April 2", "James Lloyd Breck", "James Lloyd Breck", "Nashotah House misyonunu kuran ve Minnesota ve Kaliforniya'da çalışan Episkopal misyoner rahip (1818-1876).", "Misyonerler, sınır bölgesi papazları"),
    ("April 3", "Richard of Chichester", "Chichester'lı Richard", "'Seni daha net görmek, daha çok sevmek, daha yakından izlemek' duası Protestan geleneklerinde bilinen İngiliz piskopos (1197-1253).", "Piskoposlar, Mesih'e yakınlık için dua edenler"),
    ("April 4", "Martin Luther King Jr., Martyr", "Şehit Martin Luther King Jr.", "Episkopal Kilisesi, temizlik işçilerinin yanında durduğu Memphis'te 4 Nisan 1968'de öldürülen Martin Luther King Jr.'ı anar.", "Barış yapıcılar, adalet için çalışanlar"),
    ("April 5", "Harriet Starr Cannon", "Harriet Starr Cannon", "Episkopal Kilisesi'nin kadınlar için ilk dinî tarikatı olan Aziz Mary Topluluğu'nun kurucusu Amerikalı Episkopal rahibe (1823-1896).", "Dinî topluluklar"),
    ("April 6", "Albrecht Durer, Lucas Cranach and Matthias Grunewald", "Albrecht Dürer, Lucas Cranach ve Matthias Grünewald", "Alman Rönesansı ve Reformu'nun üç büyük sanatçısı. Dürer Vahiy ve Çile ahşap baskılarını yaptı, Cranach Luther'in portresini çizdi, Grünewald Isenheim Sunağı'nı resmetti.", "Sanatçılar, baskı ustaları"),
    ("April 7", "Tikhon, Patriarch of Moscow", "Moskova Patriği Tikhon", "Amerika'da çalışan ve sonra Rus Kilisesi'ne Devrim boyunca önderlik eden, ekümenik dostluğuyla anılan Ortodoks patrik (1865-1925).", "Kilise birliği"),
    ("April 8", "William Augustus Muhlenberg", "William Augustus Muhlenberg", "İlahileri, okulları ve Kilise'nin hastalara misyonunu teşvik eden, New York'ta Aziz Luka Hastanesi'ni kuran Episkopal rahip (1796-1877).", "Hastaneler, öğretmenler"),
    ("April 10", "Mikael Agricola", "Mikael Agricola", "Finlandiya'ya ilk yazılı dilini veren ve Yeni Antlaşma'yı Fince'ye çeviren Fin piskopos ve reformcu (yaklaşık 1510-1557).", "Finlandiya, çevirmenler, dil"),
    ("April 11", "George Augustus Selwyn", "George Augustus Selwyn", "Maori dilini öğrenen ve Maoriler ile yerleşimciler arasında Kilise'yi büyütmek için ülkeyi yürüyerek dolaşan Yeni Zelanda Anglikan piskoposu (1809-1878).", "Yeni Zelanda, misyonerler"),
    ("April 12", "Adoniram Judson", "Adoniram Judson", "Burma'da yaklaşık kırk yıl hizmet eden, Kutsal Kitap'ı Burmaca'ya çeviren ve hapse ve kayıplara dayanan Amerikalı Baptist misyoner (1788-1850).", "Burma, misyonerler, çevirmenler"),
    ("April 14", "Zenaida, Philonella and Hermione", "Zenaida, Philonella ve Hermione", "Hastalara ücretsiz bakan erken ücretsiz hekimler: Zenaida ve Philonella Tarsus'lu kız kardeşlerdi, Hermione ise diyakoz Filipus'un kızıydı.", "Hekimler, hastalar"),
    ("April 15", "Corrie ten Boom", "Corrie ten Boom", "Ailesiyle birlikte Yahudileri Nazilerden saklayan Hollandalı saatçinin kızı (1892-1983). Ravensbrück'ten sağ çıktı ve son yıllarını bağışlama mesajı paylaşarak geçirdi.", "Kurtarıcılar, mahkûmlar, bağışlayanlar"),
    ("April 16", "Peter William Cassey and Annie Besant Cassey", "Peter William Cassey ve Annie Besant Cassey", "Cheltenham'da misyon kilisesini kuran ve Philadelphia'daki cemaatlerinin önderleri olan bir Episkopal diyakoz (1831-1917) ve eşi (1843-1875).", "Diyakozlar, hizmetteki aileler"),
    ("April 17", "Kateri Tekakwitha", "Kateri Tekakwitha", "1676'da vaftiz edilen, imanı için güçlüklere dayanan ve dua örneği olan Mohawk-Algonquin kadın (1656-1680). Anglikanlar ve Katolikler tarafından onurlandırılır.", "Kızılderililer, reddedilenler"),
    ("April 18", "The Diet of Worms", "Worms Diyeti", "18 Nisan 1521'de Martin Luther İmparator önünde durdu ve Kutsal Yazılar'dan ve apaçık akıldan hatasının gösterilmesi dışında geri çekilmeyi reddetti. 'Ben buradayım', diye eklediği söylenir.", "Vicdanı için ayakta duranlar"),
    ("April 19", "Philipp Melanchthon's Death and Olaus Petri", "Philipp Melanchthon'un Ölümü ve Olaus Petri", "Philipp Melanchthon 19 Nisan 1560'ta öldü; İsveçli reformcular Olaus Petri (1493-1552) ve kardeşi Laurentius Petri (1499-1573) İsveç'e Kutsal Kitap'ı ve kilise düzenini vermeleriyle anılır.", "Reformcular, çevirmenler"),
    ("April 20", "Johannes Bugenhagen", "Johannes Bugenhagen", "Luther'in Wittenberg'deki papazı olan, kuzey Almanya ve Danimarka'da Lutheran kiliseyi örgütleyen Alman papaz ve reformcu (1485-1558).", "Papazlar, kilise örgütleyicileri"),
    ("April 21", "Anselm of Canterbury", "Canterbury'li Anselm", "'Cur Deus Homo'yu yazan, ilahiyatı 'anlayış arayan iman' olarak tanımlayan ve keşişlerine nazik bir papaz olan Canterbury Başpiskoposu (yaklaşık 1033-1109).", "İlahiyatçılar, öğrenciler"),
    ("April 22", "Day of Creation", "Yaratılış Günü", "Lutheran takvimi, Dünya Günü'ne yakın olarak yaratılış için şükretmeye ve onun bakımına yeniden bağlanmaya bir gün ayırır.", "Bahçıvanlar, yaratılışın kâhyaları"),
    ("April 23", "Toyohiko Kagawa", "Toyohiko Kagawa", "Kobe gecekondularında yaşayan, kooperatifler ve hastaneler kuran Japon Hıristiyan, papaz, işçi örgütleyicisi ve yazar (1888-1960).", "Yoksullar, sosyal reformcular"),
    ("April 24", "Johann Walter", "Johann Walter", "Luther'in arkadaşı olan ve ilk Protestan koro kitabını yapan, Reform'un müziğini şekillendiren Alman besteci (1496-1570).", "Kilise müzisyenleri, korolar"),
    ("April 27", "Zita of Tuscany", "Toskana'lı Zita", "Lucca'da bir haneye büyük sadakatle hizmet eden ve yoksullara cömertçe veren ev hizmetçisi (yaklaşık 1218-1272).", "Ev işçileri"),
    ("April 29", "Catherine of Siena", "Sienalı Catherine", "Papa'yı Roma'ya dönmeye çağıran ve 'Diyalog'u yazan İtalyan mistik ve üçüncü tarikat üyesi (1347-1380). Lutheranlar ve Anglikanlar onu Kilise'nin öğretmeni olarak anar.", "Mistikler, hemşireler, İtalya"),

    ("May 1", "Philip and James, Apostles", "Havariler Filipus ve Yakup", "Filipus Nathanael'i İsa'ya getirdi ve 'bize Baba'yı göster' dedi; Küçük Yakup Kudüs kilisesine önderlik etti. Her ikisi de Lutheran ve Anglikan takvimlerinde 1 Mayıs'ta anılır.", "Havariler, Kilise"),
    ("May 2", "Athanasius of Alexandria", "İskenderiyeli Athanasius", "İznik'te Mesih'in tanrılığını savunan ve beş kez sürgüne gönderilen İskenderiye Piskoposu (yaklaşık 296-373). Enkarnasyon üzerine mektubu yaygın okunur.", "İnanç bildirisinin savunucuları"),
    ("May 3", "Elisabeth Cruciger", "Elisabeth Cruciger", "Luther'in arkadaşı, eski rahibe olan ve Lutheran geleneğinde bir kadının yazdığı ilk ilahi olan 'Herr Christ, der einig Gotts Sohn'u yazan Alman ilahi yazarı (yaklaşık 1500-1535).", "İlahi yazarları, kadın şairler"),
    ("May 4", "Monica", "Monica", "Oğlunun dönüşümüne dek yıllarca onun için dua eden Hippo'lu Augustinus'un annesi (332-387). Lutheranlar ve Anglikanlar onu sadık dua için anar.", "Anneler, çocukları için dua edenler"),
    ("May 5", "Frederick the Wise", "Bilge Frederick", "Worms Diyeti'nden sonra Luther'i koruyan ve Reform'un yayılmasına yardım eden Saksonya Seçici Prensi (1463-1525). Basiretli bir hükümdar ve öğrenmenin hamisi.", "Hükümdarlar, reformcuların koruyucuları"),
    ("May 6", "George of Lydda", "Lydda'lı George", "Birçok Kilise'nin onurlandırdığı, İngiltere'nin koruyucusu asker ve şehit (ö. yaklaşık 304). Anglikanlar bayramını Nisan'da, bazı takvimler Mayıs'ta tutar.", "Askerler, İngiltere"),
    ("May 7", "Carl F. W. Walther", "Carl F. W. Walther", "Lutheran Kilisesi-Missouri Sinodu'nun ilk başkanı ve 'Yasa ve İncil'in yazarı Alman-Amerikalı Lutheran papaz ve ilahiyatçı (1811-1887).", "Papazlar, ilahiyatçılar"),
    ("May 9", "Nicolaus Ludwig von Zinzendorf", "Nicolaus Ludwig von Zinzendorf", "Moravya mültecilerini Herrnhut'taki mülküne kabul eden, dünyanın dört bir yanına misyoner gönderen ve ilahiler yazan Alman kont (1700-1760).", "Moravyalılar, misyonerler"),
    ("May 1", "David Livingstone", "David Livingstone", "Afrika'yı baştan başa dolaşan, köleliğe karşı mücadele eden ve Bangweulu Gölü yakınında ölen İskoç misyoner ve kâşif (1813-1873). Cesedi arkadaşlarınca kıyıya taşındı.", "Afrika, misyonerler, kâşifler"),
    ("May 11", "Johann Arndt and Jacob Boehme", "Johann Arndt ve Jacob Boehme", "İçsel bağlılığı vurgulayan iki Alman ruhsal yazar: 'Gerçek Hıristiyanlık'ın yazarı Arndt (1555-1621) ve ayakkabıcı mistik Boehme (1575-1624).", "Adanmışlık yazarları"),
    ("May 12", "Florence Nightingale's Birthday", "Florence Nightingale'in Doğum Günü", "Çalışmasını Tanrı'nın bir çağrısı olarak anlayan, modern hemşireliği kuran ve askeri hastaneleri ıslah eden İngiliz hemşire (12 Mayıs 1820'de doğdu).", "Hemşireler, hastane çalışanları"),
    ("May 13", "Frances Perkins", "Frances Perkins", "Episkopal imanıyla yönlendirilen, Sosyal Güvenlik'in ve adil çalışma yasalarının oluşturulmasına yardım eden, ABD kabinesindeki ilk kadın olan Amerikalı kamu görevlisi (1880-1965).", "Kamu görevlileri, işçiler"),
    ("May 15", "Pachomius of Tabenissi", "Tabennisi'li Pachomius", "Keşişleri dua ve ortak çalışma kuralı altında topluluklar halinde örgütleyen toplu manastır yaşamının Mısırlı kurucusu (yaklaşık 292-348).", "Keşişler"),
    ("May 17", "Thurgood Marshall", "Thurgood Marshall", "Brown v. Board of Education davasını savunan ve yasa önünde eşitlik için çalışan, ilk Siyah Yüksek Mahkeme yargıcı Amerikalı hukukçu (1908-1993).", "Hukukçular, kamu görevlileri"),
    ("May 18", "Erik of Sweden", "İsveç'li Erik", "Kilise'yi destekleyen ve Ayin sırasında öldürülen adil bir hükümdar olan İsveç Kralı IX. Eric (ö. 1160). İsveç'in koruyucusu olarak onurlandırılır.", "İsveç, hükümdarlar"),
    ("May 19", "Dunstan", "Dunstan", "İngiliz manastırlarını yenileyen ve krallara danışmanlık eden zanaatkâr, müzisyen ve reformcu Canterbury Başpiskoposu (yaklaşık 909-988).", "Zanaatkârlar, müzisyenler"),
    ("May 20", "Alcuin of York", "York'lu Alcuin", "Charlemagne'ın saray okuluna önderlik eden ve Avrupa'da öğrenmeyi teşvik eden İngiliz bilgin ve diyakoz (yaklaşık 735-804).", "Öğretmenler, bilginler"),
    ("May 21", "Helena, Mother of Constantine", "Konstantin'in Annesi Helena", "Kudüs'e hac yapan ve kutsal yerlerde kiliseler yaptıran imparatoriçe (yaklaşık 250-330). Lutheranlar ve Anglikanlar onu 21 ya da 22 Mayıs'ta anar.", "Hacılar, kilise inşa edenler"),
    ("May 22", "Helena and the Care of Holy Places", "Helena ve Kutsal Yerlerin Bakımı", "Episkopal Kilisesi, Mesih'in yaşadığı ve öldüğü yerlere bakımı nedeniyle Helena'yı onurlandırır.", "Hacılar"),
    ("May 24", "John Wesley's Heart Warmed at Aldersgate", "John Wesley'nin Aldersgate'te Isınan Yüreği", "24 Mayıs 1738'de John Wesley, Londra'da Aldersgate Sokağı'ndaki bir toplantıya katıldı ve yüreğinin 'garipçe ısındığını' hissetti. Kurtuluş için yalnız Mesih'e güvendi. Lutheran takvimi bu günde Kopernik ve Euler'i de anar.", "Metodistler, müjdeciler"),
    ("May 25", "Bede the Venerable", "Saygıdeğer Bede", "'İngiliz Halkının Kilise Tarihi'ni yazan İngiliz keşiş ve tarihçi (yaklaşık 673-735). Lutheranlar ve Anglikanlar onu 25 Mayıs'ta anar.", "Tarihçiler, bilginler"),
    ("May 26", "Augustine of Canterbury", "Canterbury'li Augustinus", "Büyük Gregorius tarafından 597'de Anglo-Saksonlara İncil'i getirmek için gönderilen Canterbury'nin ilk başpiskoposu (ö. 605).", "İngiltere, misyonerler"),
    ("May 28", "Mechthild of Magdeburg", "Magdeburg'lu Mechthild", "Beguine olan ve ruhun Tanrı özlemini anlatan 'Tanrılığın Akan Işığı'nı yazan Alman mistik (yaklaşık 1207-yaklaşık 1282).", "Mistikler, yazarlar"),
    ("May 29", "Juraj Tranovsky", "Juraj Tranovsky", "Genellikle 'Slavların Luther'i' denen, ilahi kitabı 'Cithara Sanctorum' hâlâ kullanılan Slovak Lutheran papaz ve ilahi yazarı (1592-1637).", "İlahi yazarları, Slovakya"),
    ("May 30", "Joan of Arc", "Joan of Arc", "Göksel sesler olduğuna inandığı şeylerle yönlendirilerek Fransız ordusuna önderlik etmeye yardım eden ve sapkınlıkla suçlanıp idam edilen Fransız köylü kızı (yaklaşık 1412-1431). Kilise'ce aklanmış, birçok gelenek tarafından onurlandırılır.", "Fransa, askerler, haksız yere mahkûm edilenler"),

    ("June 2", "Blandina and the Martyrs of Lyons", "Blandina ve Lyon Şehitleri", "177'de Lyon'da diğer birçok Hıristiyan'la birlikte işkence görüp öldürülen bir köle kadın. Cesareti diğer şehitleri güçlendirdi.", "Zulüm görenler, köleler"),
    ("June 3", "Hudson Taylor's Death and the Martyrs of Uganda", "Hudson Taylor'ın Ölümü ve Uganda Şehitleri", "Hudson Taylor 3 Haziran 1905'te Çin'de öldü. Aynı tarih, 1886'da Mesih'i inkâr etmeyi reddettikleri için öldürülen Uganda şehitlerini de anar.", "Çin, Uganda, misyonerler"),
    ("June 4", "John XXIII", "XXIII. Yuhanna", "İkinci Vatikan Konsili'ni toplayan ve Katolik olmayan gözlemcileri davet eden, 1958-1963 papası. Episkopallar ve Lutheranlar onu sıcaklığı ve açıklığı için anar.", "Kilise birliği"),
    ("June 7", "Chief Seattle", "Şef Seattle", "Katolik olarak vaftiz edilen, yerleşimcilerle barışçıl ilişkiler arayan ve toprağa saygı için konuşan Duwamish ve Suquamish halkının önderi (yaklaşık 1786-1866).", "Yerli halklar, barış yapıcılar"),
    ("June 8", "Melania the Elder", "Yaşlı Melania", "Servetini veren, Mısır ve Kudüs'e giden ve keşişleri ve sürgünleri destekleyen Romalı soylu kadın (yaklaşık 342-410).", "Hayırseverler, dullar"),
    ("June 9", "Columba, Aidan and Bede", "Columba, Aidan ve Bede", "Britanya Adaları'nın üç azizi: Iona'yı kuran Columba (ö. 597); Northumbria'yı müjdeleyen Aidan (ö. 651); ve İngiliz Kilisesi'nin tarihçisi Bede (ö. 735).", "İskoçya, İngiltere, misyonerler"),
    ("June 10", "Ephrem of Nisibis", "Nusaybin'li Ephraim", "İlahiler ve tefsirler yazan, kıtlık zamanında yoksullara bakan Süryani diyakoz ve şair (yaklaşık 306-373). Batı'da Kilise Doktoru'dur.", "Diyakozlar, ilahi yazarları"),
    ("June 11", "Barnabas, Apostle", "Havari Barnaba", "Pavlus'u havarilere tanıtan ve ilk misyon yolculuğunda onunla seyahat eden 'cesaret oğlu' denen Kıbrıslı Levili.", "Cesaretlendirenler, misyonerler"),
    ("June 12", "Enmegahbowh", "Enmegahbowh", "Episkopal Kilisesi'nde kutsanan ilk Kızılderili olan, 1862 Dakota Savaşı sırasında yerleşimcileri koruyan Ojibwe rahip ve misyoner (yaklaşık 1810-1902).", "Kızılderililer, barış yapıcılar"),
    ("June 13", "The First Book of Common Prayer", "İlk Duaların Ortak Kitabı", "Başpiskopos Cranmer döneminde 1549'da yayımlanan Duaların Ortak Kitabı, İngilizce konuşan kiliseye kendi dilinde ibadet verdi.", "İbadet edenler"),
    ("June 14", "Basil, Gregory and Macrina", "Basil, Gregory ve Macrina", "Kapadokyalı Babalar Büyük Basil, Nazianzos'lu Gregory ve Nyssalı Gregory ile kız kardeşleri Macrina; Teslis'i ve dua ve hizmet hayatını öğrettiler.", "İlahiyatçılar, öğretmenler"),
    ("June 15", "Evelyn Underhill", "Evelyn Underhill", "'Mistisizm'in yazarı, yirminci yüzyılın dua ve inziva üzerine en etkili öğretmenlerinden biri olan İngiliz Anglikan yazar (1875-1941).", "Yazarlar, inziva önderleri"),
    ("June 16", "Joseph Butler", "Joseph Butler", "'Dinin Analojisi' adlı eseriyle çağının deistlerine yanıt veren Anglikan piskopos ve filozof (1692-1752).", "Filozoflar, piskoposlar"),
    ("June 17", "Marina the Monk", "Keşiş Marina", "Marinos adlı bir keşiş kılığında bir erkek manastırında yaşayan beşinci yüzyıl genç kadını. Asılsız suçlama karşısındaki sabrı anılır.", "Haksız yere suçlananlar"),
    ("June 18", "Bernard Mizeki", "Bernard Mizeki", "Zimbabwe'de Shona halkına öğreten ve Mashonaland ayaklanmasında öldürülen Mozambikli ilmihal öğretmeni (yaklaşık 1861-1896). Şehit olarak onurlandırılır.", "İlmihal öğretmenleri, Zimbabwe"),
    ("June 19", "Charles Haddon Spurgeon's Birthday", "Charles Haddon Spurgeon'un Doğum Günü", "19 Haziran 1834'te Essex'in Kelvedon kasabasında doğdu. 'Vaizlerin Prensi', on beş yaşında bir kar fırtınasında Yeşaya 45:22 üzerine basit bir vaaz duyarak dönüştü.", "Vaizler, dönüşenler"),
    ("June 21", "Onesimos Nesib", "Onesimos Nesib", "Bir zamanlar köle olan, Kutsal Kitap'ı Oromo diline çeviren ve İsveç Lutheran misyonlarınca desteklenen halkı arasında müjdeyi yayan Etiyopyalı Oromo (yaklaşık 1856-1931).", "Çevirmenler, Etiyopya"),
    ("June 22", "Alban", "Alban", "Bir rahibi barındırıp onun yerine geçen ve başı kesilen Roma askeri; Britanya'nın ilk şehidi (yaklaşık 304). Saint Albans şehri onun adını taşır.", "Britanya, barınak verenler"),
    ("June 23", "Etheldreda of Ely", "Ely'li Etheldreda", "Ely manastırını kuran ve kraliyet hayatını bırakıp sadelik içinde yaşayan Anglo-Sakson kraliçe ve başrahibe (yaklaşık 636-679).", "Başrahibeler, Doğu Anglia"),
    ("June 25", "The Augsburg Confession and Philip Melanchthon", "Augsburg İtirafı ve Philipp Melanchthon", "25 Haziran 1530'da Lutheran prensler, Augsburg Diyeti'nde İmparator V. Charles'a Lutheran kilisenin imanını belirten Augsburg İtirafı'nı sundu.", "İtirafçılar, Lutheran kiliseler"),
    ("June 26", "Isabel Florence Hapgood", "Isabel Florence Hapgood", "Ortodoks litürjik metinleri İngilizceye çevirip kiliseler arasında köprüler kuran Amerikalı çevirmen ve ekümenist (1851-1928).", "Çevirmenler, ekümenistler"),
    ("June 27", "Cyril of Alexandria", "İskenderiyeli Cyril", "Efes Konsili'nde Meryem için Theotokos unvanını savunan ve Kutsal Yazılar üzerine tefsirler yazan İskenderiye Başpiskoposu (yaklaşık 376-444).", "İlahiyatçılar"),
    ("June 28", "Irenaeus of Lyons", "Lyon'lu Irenaeus", "'Sapkınlıklara Karşı'yı yazan ve Tanrı'nın planının tarihte ortaya çıktığını öğreten Lyon Piskoposu (yaklaşık 130-202). Lutheranlar ve Anglikanlar onu imanın öğretmeni olarak onurlandırır.", "İlahiyatçılar, piskoposlar"),
    ("June 30", "Commemoration of Paul the Apostle", "Havari Pavlus'un Anılışı", "Lutheran takvimi, mektupları Yeni Antlaşma'nın büyük bölümünü oluşturan uluslara havari Pavlus'un anılışını tamamlar.", "Havariler, misyonerler"),
]
